import errno
import logging
import stat
from abc import ABCMeta, abstractmethod
from contextlib import contextmanager
from io import StringIO
from shlex import quote

import paramiko
from scp import SCPClient

from .workarounds import set_default_open_session_timeout

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class FileProtocol:
    """Base class for classes that implement file protocols.

    Both :py:class:`SFTP` and :py:class:`SCP` classes contain the interface
    outlined here. Only exceptions and idiosyncratic behaviors are noted in the
    documentation for their methods.
    """

    __metaclass__ = ABCMeta

    def __init__(self):
        self._fp_client = None

    def put(self, local_path, remote_path, timeout=None):
        """Copy a local file (``local_path``) to the remote host (``remote_path``)."""
        with self._set_channel_timeout(timeout):
            self._fp_client.put(local_path, remote_path)

    def get(self, remote_path, local_path, timeout=None):
        """Copy a remote file (``remote_path``) to the local host (``local_path``)."""
        with self._set_channel_timeout(timeout):
            self._fp_client.get(remote_path, local_path)

    def close(self):
        """Close the file protocol client."""
        self._fp_client.close()

    @abstractmethod
    def stat(self, remote_path, timeout=None):
        """Retrieve stat information about a file from the remote system.

        Objects returned by this method have the same interface as
        :py:class:`paramiko.SFTPAttributes`.
        """
        raise NotImplementedError

    @abstractmethod
    def open(self, remote_path, mode="r", bufsize=-1):
        """Return a file-like object that corresponds to the remote file.

        Semantics of this method should resemble the Python's builtin
        ``open()`` function.
        """
        raise NotImplementedError

    @abstractmethod
    def _set_channel_timeout(self, timeout):
        """Temporarily set a timeout of an already opened FP channel.

        Use this as a context manager. The old timeout will be restored on
        exit.
        """
        raise NotImplementedError

    @abstractmethod
    def listdir(self, path="."):
        """Return a list of names of files present under the given path.

        This should never return ``.`` and ``..``. It should mimic ``os.listdir()`` as
        closely as possible. The order of the items in the returned list is not
        guaranteed.
        """
        raise NotImplementedError

    def exists(self, remote_path, timeout=None):
        """Return ``True`` if a file exists on the remote, ``False`` otherwise."""
        try:
            self.stat(remote_path, timeout)
            exists = True
        except OSError:
            exists = False
        return exists


class SFTP(FileProtocol):
    """Provides operations on files via SFTP protocol.

    Do not instantiate this class directly - use the
    :py:attr:`SSHConnection.files` property (or the same property of proxied
    equivalent, :py:class:`ProxySSHConnection`).

    **For the full description of the interface of this class, see**
    :py:class:`FileProtocol`.
    """

    def __init__(self, ssh_client, timeout=None):
        super().__init__()
        logger.debug("Opening SFTP client.")

        transport = ssh_client.get_transport()
        with set_default_open_session_timeout(transport, timeout):
            self._fp_client = paramiko.SFTP.from_transport(transport)

        logger.debug("SFTP client opened.")

    def stat(self, remote_path, timeout=None):
        """Retrieve stat information about a file from the remote system.

        :rtype: paramiko.SFTPAttributes
        """
        with self._set_channel_timeout(timeout):
            return self._fp_client.stat(remote_path)

    def open(self, remote_path, mode="r", bufsize=-1):
        """Return a file-like object that corresponds to the remote file.

        The arguments for this method mimic the arguments of Python's
        ``open()`` builtin function.

        :rtype: paramiko.SFTPFile
        """
        return self._fp_client.open(remote_path, mode=mode, bufsize=bufsize)

    def listdir(self, path="."):
        """Return the list of the filenames of files in a directory under ``path``.

        The order of the files in the list is arbitrary. The list does not
        contain ``.`` and ``..`` entries seen in ``ls -a`` command.

        :rtype: list[str]
        """
        return self._fp_client.listdir(path=path)

    @contextmanager
    def _set_channel_timeout(self, timeout):
        channel = self._fp_client.get_channel()
        old_timeout = channel.gettimeout()
        channel.settimeout(timeout)
        try:
            yield
        finally:
            channel.settimeout(old_timeout)


class SCP(FileProtocol):
    """Provides operations on files via SCP protocol.

    Do not instantiate this class directly - use the
    :py:attr:`SSHConnection.files` property (or the same property of proxied
    equivalent, :py:class:`ProxySSHConnection`).
    """

    # TODO: wrap scp.SCPException into SCPError.

    def __init__(self, ssh_client, timeout=None):
        super().__init__()
        logger.debug("Opening SCP client.")

        transport = ssh_client.get_transport()
        with set_default_open_session_timeout(transport, timeout):
            self._fp_client = SCPClient(transport)
        self._ssh_client = ssh_client

        logger.debug("SCP client opened.")

    @contextmanager
    def _set_channel_timeout(self, timeout):
        old_timeout = self._fp_client.socket_timeout
        self._fp_client.socket_timeout = timeout
        try:
            yield
        finally:
            self._fp_client.socket_timeout = old_timeout

    def stat(self, remote_path, timeout=None):
        """
        Fetch stat information about a file on the remote.

        This implementation sends "stat" command to the remote and parses the
        output / exit_status of it.

        :raises IOError: if the exit code of the ``stat`` command is ``1``.
        :raises SCPError: if the exit code of the stat command is greater than ``1``.
        :rtype: SCPAttributes
        """
        output, error_msg, exit_status = self._send_stat_cmd(remote_path, timeout)
        logger.debug(
            "Stat exited with exit code %d (stdout: %r, stderr: %r).",
            exit_status,
            output,
            error_msg,
        )
        self._handle_errors_if_any("stat", error_msg, exit_status)
        return SCPAttributes.from_str(output)

    def _send_stat_cmd(self, remote_path, timeout):
        command = self._generate_stat_cmd(remote_path)
        streams = self._ssh_client.exec_command(command, timeout=timeout)
        output, error_msg, exit_status = self._get_output(streams)
        return output, error_msg, exit_status

    @staticmethod
    def _generate_stat_cmd(remote_path):
        remote_path = quote(remote_path)
        printf = SCPAttributes.FORMAT.format("%s", "%u", "%g", "%f", "%X", "%Y")
        return f"stat -c '{printf}' {remote_path}"

    @staticmethod
    def _get_output(streams):
        output = streams[1].read().decode(errors="ignore")
        error_msg = streams[2].read().decode(errors="ignore")
        exit_status = streams[2].channel.recv_exit_status()
        return output, error_msg, exit_status

    @staticmethod
    def _handle_errors_if_any(command, error_msg, exit_status):
        if exit_status == 0:
            return
        if exit_status == 1:
            raise OSError(errno.ENOENT, error_msg)
        if exit_status == 127:
            raise SCPError(f"{command} failed: command not found.")
        if exit_status != 0:
            raise SCPError(f"{command} failed with unknown exit status.")

    def open(self, remote_path, mode="r", bufsize=-1):
        """Return a file-like object that corresponds to the remote file.

        This method is mostly a stub meant to provide a limitted parity with
        :py:func:`SFTP.open()`:

        * Only the ``"r"`` mode is supported.
        * The ``bufsize`` parameter is completely ignored. There's no
          additional buffering implemented.
        * The contents of the file are read using the ``cat`` command at the
          point of calling this method.

        :rtype: io.StringIO
        """
        if mode != "r":
            raise NotImplementedError("modes different than 'r' are not supported yet.")
        if bufsize != -1:
            logger.warning("Bufsize argument is ignored in this file protocol.")

        data = self._get_file_content(remote_path)
        file_like = StringIO(data.decode("utf-8"))
        return file_like

    def _get_file_content(self, remote_path):
        remote_path = quote(remote_path)
        read_command = f"cat {remote_path}"
        logger.debug("Reading %r with command: %r", remote_path, read_command)

        streams = self._ssh_client.exec_command(read_command)
        file_content, error_msg, exit_status = self._get_output(streams)

        self._handle_errors_if_any("cat", error_msg, exit_status)

        return file_content

    def listdir(self, path="."):
        """Return the list of the filenames of files in a directory under ``path``.

        The order of the files in the list is arbitrary. The list does not
        contain ``.`` and ``..`` entries seen in ``ls -a`` command.

        For SCP, using this method will send a bash command that includes
        several bash builtins, including ``shopt`` and ``set``. Therefore this
        requires the login shell of the SSH session to be set accordingly -
        ``/bin/sh`` is unlikely to work.

        :rtype: list[str]
        """
        self._check_if_path_is_correct(path)
        command = self._generate_listdir_command(path)
        output = self._send_listdir_command(command)
        return self._parse_listdir_cmd_output(output)

    def _check_if_path_is_correct(self, path):
        if not self.exists(path):
            raise OSError(errno.ENOENT, f"No such file or directory: {path!r}")
        # TODO substitute this with self.isdir() whenever it is implemented.
        is_directory = stat.S_ISDIR(self.stat(path).st_mode)
        if not is_directory:
            raise OSError(errno.ENOTDIR, f"Not a directory: {path!r}")

    # The command generated below disables globbing with set -f. This will
    # mimic the behavior of os.listdir, which itself doesn't have any idea of
    # wildcards or patterns. Then this has to be undone via set +f to allow for
    # the '*' to be expanded. The shopt -s dotglob makes the wildcard expansion
    # include the filenames starting with '.', while nullglob makes it return
    # nothing if the directory is empty
    @staticmethod
    def _generate_listdir_command(path):
        path = quote(path)
        template = (
            "shopt -s dotglob; shopt -s nullglob; "
            "set -f; cd {}; "
            'set +f; files=(*); printf "%s\\0" "${{files[@]}}"'
        )
        return template.format(path)

    def _send_listdir_command(self, command, timeout=None):
        logger.info("Listdir performed via command: %r", command)
        streams = self._ssh_client.exec_command(command, timeout)
        output, _, exit_code = self._get_output(streams)
        if exit_code != 0:
            raise SCPError("listdir failed: command returned non-zero status.")
        return output

    @staticmethod
    def _parse_listdir_cmd_output(output):
        output = output[:-1]
        if output == "":
            return []
        byte_paths = output.split("\0")
        unicode_paths = [byte_path.decode("utf-8") for byte_path in byte_paths]

        return unicode_paths


class SCPAttributes:
    """Stores the stat result of :py:func:`SCP.stat()`.

    This class aims to follow the interface of
    :py:class:`paramiko.SFTPAttributes`, so that the two can be used
    interchangeably from perspective of the user's code.
    """

    FORMAT = "size={} uid={} gid={} mode={} atime={} mtime={}"

    @classmethod
    def from_str(cls, stat_str):
        """Create SCPAttributes object from a given string.

        The given string should be of the form SCPAttributes.FORMAT, i.e. any
        result of SCPAttributes.FORMAT.format(...) will work.
        """
        attr_dict = cls._stat_output_to_dict(stat_str)
        return cls(**attr_dict)

    def __init__(
        self, size=None, uid=None, gid=None, mode=None, atime=None, mtime=None
    ):
        self.st_size = size
        self.st_uid = uid
        self.st_gid = gid
        self.st_mode = mode
        self.st_atime = atime
        self.st_mtime = mtime

    def __repr__(self):
        repr_template = f"<{self.__class__.__name__}: [{self.FORMAT}]>"
        return repr_template.format(
            self.st_size,
            self.st_uid,
            self.st_gid,
            oct(self.st_mode),
            self.st_atime,
            self.st_mtime,
        )

    @classmethod
    def _stat_output_to_dict(cls, stat_str):
        attr_pairs = (attr_str.split("=") for attr_str in stat_str.split(" "))
        return {
            attr: int(value) if attr != "mode" else int(value, 16)
            for attr, value in attr_pairs
        }


class SCPError(Exception):
    """Raised whenever a method that uses SCP protocol fails."""


def file_protocol(ssh_client, timeout=None):
    """Open a file protocol client using existing ssh connection.

    Parameters
    ----------
    ssh_client : paramiko.SSHClient
        SSH connection used to open the new file protocol client.
    timeout : float
        Timeout used in initial operation of opening the client's channel.

    Returns
    -------
    FileProtocol
        SFTP, if the target server supports it. SCP otherwise.
    """
    try:
        protocol = SFTP(ssh_client, timeout)
        logger.debug("SFTP protocol initiated.")
    except paramiko.SSHException:
        protocol = SCP(ssh_client, timeout)
        logger.debug("SCP protocol initiated.")
    return protocol
